import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:pdfrx/pdfrx.dart';
import 'package:sickpdf/services/pdf_open_service.dart';

/// Runs against the real pdfrx engine and the repository's own fixtures.
///
/// Fixtures (both synthetic, generated by
/// `test/fixtures/generate_encrypted_pdfs.py`, no third-party documents):
/// - `test/fixtures/password_required.pdf` — user password `secret`, so it
///   cannot be opened without one.
/// - `test/fixtures/owner_encrypted.pdf` — empty user password, owner
///   permissions only, so it opens like any normal PDF.
///
/// Override the paths with `SICKPDF_PASSWORD_PDF` and
/// `SICKPDF_COMPATIBILITY_PDF` if needed.
const _defaultPasswordPdf = 'test/fixtures/password_required.pdf';
const _defaultOwnerPdf = 'test/fixtures/owner_encrypted.pdf';
const _correctPassword = 'secret';

/// A minimal, valid, unencrypted PDF so the "no password" path is proven on a
/// document that is definitely not encrypted.
Uint8List plainPdf() {
  const body = 'BT /F1 12 Tf 20 40 Td (Hello) Tj ET';
  final objects = <String>[
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 300] '
        '/Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    '<< /Length ${body.length} >>\nstream\n$body\nendstream',
  ];
  final buffer = StringBuffer('%PDF-1.4\n');
  final offsets = <int>[];
  for (var i = 0; i < objects.length; i++) {
    offsets.add(buffer.length);
    buffer.write('${i + 1} 0 obj\n${objects[i]}\nendobj\n');
  }
  final xref = buffer.length;
  buffer.write('xref\n0 ${objects.length + 1}\n0000000000 65535 f \n');
  for (final offset in offsets) {
    buffer.write('${offset.toString().padLeft(10, '0')} 00000 n \n');
  }
  buffer.write(
    'trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\n'
    'startxref\n$xref\n%%EOF\n',
  );
  return Uint8List.fromList(buffer.toString().codeUnits);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  final passwordPdf =
      Platform.environment['SICKPDF_PASSWORD_PDF'] ?? _defaultPasswordPdf;
  final ownerPdf =
      Platform.environment['SICKPDF_COMPATIBILITY_PDF'] ?? _defaultOwnerPdf;

  const service = PdfOpenService();
  late Directory cache;
  late Directory work;

  setUp(() async {
    // Keep pdfrx's native cache inside a temp directory per test.
    cache = await Directory.systemTemp.createTemp('sickpdf_open_cache_');
    work = await Directory.systemTemp.createTemp('sickpdf_open_work_');
    Pdfrx.cacheDirectoryPath = cache.path;
  });

  tearDown(() async {
    for (final directory in [cache, work]) {
      if (await directory.exists()) await directory.delete(recursive: true);
    }
  });

  Future<String> writePlain() async {
    final file = File('${work.path}${Platform.pathSeparator}plain.pdf');
    await file.writeAsBytes(plainPdf());
    return file.path;
  }

  /// Proves the fixtures really are what the tests assume, so a broken fixture
  /// cannot make the suite pass by accident.
  Future<void> requireFixtures() async {
    expect(
      File(passwordPdf).existsSync(),
      isTrue,
      reason:
          'Missing "$passwordPdf". Generate it with '
          '`python test/fixtures/generate_encrypted_pdfs.py` from the project '
          'root, or set SICKPDF_PASSWORD_PDF.',
    );
  }

  group('requiresPassword', () {
    test('a plain PDF does not require a password', () async {
      expect(await service.requiresPassword(await writePlain()), isFalse);
    });

    test('a password-protected PDF requires a password', () async {
      await requireFixtures();
      expect(await service.requiresPassword(passwordPdf), isTrue);
    });

    test('an owner-permissions PDF opens without a password', () async {
      await requireFixtures();
      expect(
        await service.requiresPassword(ownerPdf),
        isFalse,
        reason: 'an empty user password is not a lock on opening the document',
      );
    });

    test('a missing file is reported, not treated as a password', () async {
      final missing = '${work.path}${Platform.pathSeparator}nope.pdf';
      await expectLater(
        service.requiresPassword(missing),
        throwsA(
          isA<PdfOpenException>().having(
            (e) => e.wrongPassword,
            'wrongPassword',
            isFalse,
          ),
        ),
      );
    });

    test('an empty file is reported separately', () async {
      final empty = File('${work.path}${Platform.pathSeparator}empty.pdf');
      await empty.writeAsBytes(const <int>[]);
      await expectLater(
        service.requiresPassword(empty.path),
        throwsA(
          isA<PdfOpenException>().having(
            (e) => e.message,
            'message',
            contains('empty'),
          ),
        ),
      );
    });

    test('a corrupt file is not reported as needing a password', () async {
      final corrupt = File('${work.path}${Platform.pathSeparator}bad.pdf');
      await corrupt.writeAsBytes(utf8.encode('this is not a pdf at all'));
      await expectLater(
        service.requiresPassword(corrupt.path),
        throwsA(
          isA<PdfOpenException>()
              .having((e) => e.wrongPassword, 'wrongPassword', isFalse)
              .having(
                (e) => e.message,
                'message',
                allOf(
                  isNot(contains('password is incorrect')),
                  contains('damaged'),
                ),
              ),
        ),
      );
    });
  });

  group('verifyPassword', () {
    test('the correct password opens the document', () async {
      await requireFixtures();
      await expectLater(
        service.verifyPassword(passwordPdf, _correctPassword),
        completes,
      );
    });

    test('a wrong password is rejected as a password error', () async {
      await requireFixtures();
      await expectLater(
        service.verifyPassword(passwordPdf, 'wrong-password-value'),
        throwsA(
          isA<PdfOpenException>()
              .having((e) => e.wrongPassword, 'wrongPassword', isTrue)
              .having((e) => e.message, 'message', pdfWrongPasswordMessage),
        ),
      );
    });

    test('an empty password is rejected before the engine is used', () async {
      await requireFixtures();
      await expectLater(
        service.verifyPassword(passwordPdf, ''),
        throwsA(
          isA<PdfOpenException>().having(
            (e) => e.message,
            'message',
            'Enter the PDF password.',
          ),
        ),
      );
    });

    test('retrying after a wrong password succeeds', () async {
      await requireFixtures();
      await expectLater(
        service.verifyPassword(passwordPdf, 'first-guess'),
        throwsA(isA<PdfOpenException>()),
      );
      // The same service instance must remain usable for a second attempt.
      await expectLater(
        service.verifyPassword(passwordPdf, _correctPassword),
        completes,
      );
    });

    test('the password never appears in the error message', () async {
      await requireFixtures();
      const secret = 'super-secret-guess-42';
      try {
        await service.verifyPassword(passwordPdf, secret);
        fail('Expected the wrong password to be rejected.');
      } on PdfOpenException catch (error) {
        expect(error.message, isNot(contains(secret)));
        expect(error.toString(), isNot(contains(secret)));
      }
    });

    test('a password on an unencrypted PDF still opens it', () async {
      final path = await writePlain();
      await expectLater(service.verifyPassword(path, 'irrelevant'), completes);
    });
  });

  group('password provider', () {
    test('answers once and then stops', () {
      final provider = pdfPasswordProviderFor('secret');
      expect(provider(), 'secret');
      for (var i = 0; i < 10; i++) {
        expect(provider(), isNull);
      }
    });
  });
}